package vn.smartfarm.iot.telemetry;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.ObjectProvider;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.control.*;import vn.smartfarm.iot.automation.WateringRule;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class PumpHttpIntentTest {
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired PlatformTransactionManager manager;@Autowired ObjectProvider<CommandTransport> providers;@Autowired WateringRule rule;@Autowired MockMvc mvc;@MockitoBean CommandTransport transport;
 final UUID boot=UUID.fromString("81000000-0000-4000-8000-000000000001");
 @BeforeEach void setup()throws Exception{jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport);when(transport.controlConnected()).thenReturn(true);report(boot);}
 void report(UUID b)throws Exception{var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",b.toString()).put("sequence",1).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState","OFF").put("safetyLockout",false);p.putObject("commandFence").put("version",1).put("lastOrdinal",0).put("restartRequired",false);pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));}
 PumpCommandFencing.HttpIntent request(String action){var c=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,action.equals("ON")?5:null,action.equals("OFF")?null:c.bootId(),c.revision(),c.asOf());}
 long count(){return jdbc.queryForObject("SELECT COUNT(*) FROM pump_command",Long.class);}
 @Test void duplicateOnIsOnePublishAndDoesNotPauseNewerRule(){var r=request("ON");var first=rule.manualRequest(r);jdbc.update("UPDATE watering_rule SET enabled=true");var again=rule.manualRequest(r);assertEquals(first.command().commandId(),again.command().commandId());assertTrue(rule.state().enabled());verifyPublish(1);assertEquals(1,count());}
 @Test void sameIdChangedInputConflicts(){var r=request("ON");rule.manualRequest(r);var changed=new PumpCommandFencing.HttpIntent(r.requestId(),"ON",6,r.expectedBootId(),r.intentRevision(),r.reviewedAt());assertEquals(409,assertThrows(ResponseStatusException.class,()->rule.manualRequest(changed)).getStatusCode().value());verifyPublish(1);}
 @Test void onReviewedBeforeOffCannotReserveEvenAfterPendingCleared(){var on=request("ON");rule.manualRequest(request("OFF"));jdbc.update("UPDATE pump_command SET state='TIMED_OUT'");assertThrows(ResponseStatusException.class,()->rule.manualRequest(on));assertEquals(1,count());verifyPublish(1);}
 @Test void offlineOffStillPersistsBarrierAndFailedReceipt(){var old=request("ON");when(transport.controlConnected()).thenReturn(false);var r=rule.manualRequest(request("OFF"));assertEquals("FAILED",r.command().state());assertEquals("MQTT_UNAVAILABLE",r.command().errorCode());when(transport.controlConnected()).thenReturn(true);assertThrows(ResponseStatusException.class,()->rule.manualRequest(old));verifyPublish(0);assertEquals(1,count());}
 @Test void emergencyLegacyOffAlsoInvalidatesOldHttpIntent()throws Exception{var old=request("ON");mvc.perform(post("/api/v1/actuators/PUMP01/commands").contentType("application/json").content("{\"action\":\"OFF\"}")).andExpect(status().isAccepted());assertThrows(ResponseStatusException.class,()->rule.manualRequest(old));verifyPublish(1);}
 @Test void oldOnAndResetEndpointAreRejectedInProtectedProfile()throws Exception{for(String body:List.of("{\"action\":\"ON\",\"durationSeconds\":5}","{\"action\":\"RESET_LOCKOUT\"}"))mvc.perform(post("/api/v1/actuators/PUMP01/commands").contentType("application/json").content(body)).andExpect(status().isConflict());assertEquals(0,count());verifyPublish(0);}
 @Test void newBootRejectsPreviouslyReviewedOn()throws Exception{var r=request("ON");report(UUID.randomUUID());assertThrows(ResponseStatusException.class,()->rule.manualRequest(r));assertEquals(0,count());}
 @Test void restartInvalidatesReviewButDuplicateStoredRequestCanBeRead(){var a=request("ON");rule.manualRequest(a);fencing.invalidateHttpOnStartup();assertEquals(a.requestId(),rule.manualRequest(a).command().commandId());var old=new PumpCommandFencing.HttpIntent(UUID.randomUUID(),"RESET_LOCKOUT",null,a.expectedBootId(),a.intentRevision(),a.reviewedAt());assertThrows(ResponseStatusException.class,()->rule.manualRequest(old));verifyPublish(1);}
 @Test void reviewDeadlineAndFutureReviewRejectWithoutPausing(){jdbc.update("UPDATE watering_rule SET enabled=true");for(Instant at:List.of(Instant.now().minusSeconds(20),Instant.now().plusSeconds(20))){var r=request("ON");var bad=new PumpCommandFencing.HttpIntent(r.requestId(),r.action(),r.durationSeconds(),r.expectedBootId(),r.intentRevision(),at);assertThrows(ResponseStatusException.class,()->rule.manualRequest(bad));}assertTrue(rule.state().enabled());assertEquals(0,count());}
 @Test void lostPublishResultIsSavedAndReplayedAsReadOnly()throws Exception{doThrow(new RuntimeException("unknown")).when(transport).publishCommand(any());var r=request("ON");assertEquals("PUBLISH_UNCERTAIN",rule.manualRequest(r).command().state());when(transport.controlConnected()).thenReturn(false);assertEquals("PUBLISH_UNCERTAIN",rule.manualRequest(r).command().state());verifyPublish(1);}
 @Test void manualHoldAndReservationRollbackTogether(){var r=request("ON");assertThrows(RuntimeException.class,()->fencing.createHttp(r,()->{jdbc.update("UPDATE watering_rule SET enabled=true");throw new RuntimeException("rollback");}));assertEquals(0,count());assertFalse(rule.state().enabled());verifyPublish(0);}
 @Test void lookupBeyondTwentyAndReadOnlyRecoveryAfterFlagsOff(){var first=request("OFF");rule.manualRequest(first);for(int i=0;i<22;i++)rule.manualRequest(request("OFF"));var stopped=new PumpCommandFencing(jdbc,mapper,providers,manager,false,false);assertEquals(first.requestId(),stopped.createHttp(first,()->{throw new AssertionError();}).command().commandId());assertEquals(first.requestId(),stopped.lookupHttp(first.requestId()).command().commandId());verifyPublish(23);}
 @Test void sameUuidAcrossTwoInstancesPublishesAndHoldsOnce()throws Exception{var r=request("ON");var other=new PumpCommandFencing(jdbc,mapper,providers,manager,true,true);other.invalidateHttpOnStartup();r=request("ON");final var req=r;var gate=new CountDownLatch(1);AtomicInteger holds=new AtomicInteger();try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{gate.await();return fencing.createHttp(req,holds::incrementAndGet);});var b=pool.submit(()->{gate.await();return other.createHttp(req,holds::incrementAndGet);});gate.countDown();assertEquals(a.get(5,TimeUnit.SECONDS).command().commandId(),b.get(5,TimeUnit.SECONDS).command().commandId());}assertEquals(1,holds.get());verifyPublish(1);}
 @Test void startupGateStopsNewHttpBeforeRecovery(){var booting=new PumpCommandFencing(jdbc,mapper,providers,manager,true,true);assertEquals(503,assertThrows(ResponseStatusException.class,()->booting.createHttp(request("ON"),()->{})).getStatusCode().value());assertEquals(0,count());}
 @Test void malformedHttpAndGetByIdContract()throws Exception{String url="/api/v1/actuators/PUMP01/requests";for(String body:List.of("{}","{\"action\":true}","{\"requestId\":1,\"requestId\":2}"))mvc.perform(post(url).contentType("application/json").content(body)).andExpect(status().isBadRequest());var r=request("ON");mvc.perform(post(url).contentType("application/json").content(mapper.writeValueAsBytes(r))).andExpect(status().isAccepted()).andExpect(jsonPath("$.command.commandId").value(r.requestId().toString()));mvc.perform(get(url+"/"+r.requestId())).andExpect(status().isOk()).andExpect(jsonPath("$.request.intentRevision").value(r.intentRevision()));mvc.perform(get(url+"/"+UUID.randomUUID())).andExpect(status().isNotFound());}
 void verifyPublish(int n){try{verify(transport,times(n)).publishCommand(any());}catch(Exception e){throw new RuntimeException(e);}}
}
